-- SEC-080 Insurance básico. Aplicar primeiro em DEV. Nenhuma integração externa é presumida.
CREATE TABLE insurance_quote_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),property_id uuid NOT NULL REFERENCES properties(id),asset_id uuid REFERENCES assets(id),requested_by_user_id uuid NOT NULL REFERENCES app_users(id),product_type text NOT NULL CHECK(product_type IN('home','rural_property','asset','machinery','equipment','vehicle','liability')),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','requested','under_review','quoted','declined','accepted','cancelled')),security_data_use boolean NOT NULL DEFAULT false,security_consent_id uuid,notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT insurance_quote_notes_length CHECK(notes IS NULL OR length(notes)<=4000));CREATE INDEX idx_insurance_quotes_property_status ON insurance_quote_requests(property_id,status,created_at DESC);
CREATE TABLE insurance_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),property_id uuid NOT NULL REFERENCES properties(id),asset_id uuid REFERENCES assets(id),product_type text NOT NULL CHECK(product_type IN('home','rural_property','asset','machinery','equipment','vehicle','liability')),insurer_name text NOT NULL,policy_number text,coverage_summary text,valid_from date NOT NULL,valid_until date NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','pending_renewal','expired','cancelled')),renewal_status text NOT NULL DEFAULT 'not_started' CHECK(renewal_status IN('not_started','requested','quoted','renewed','declined')),created_by_user_id uuid NOT NULL REFERENCES app_users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT insurance_policy_dates_valid CHECK(valid_until>=valid_from),CONSTRAINT insurance_coverage_length CHECK(coverage_summary IS NULL OR length(coverage_summary)<=5000));CREATE INDEX idx_insurance_policies_property_expiry ON insurance_policies(property_id,valid_until,status);
CREATE TABLE insurance_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),policy_id uuid NOT NULL REFERENCES insurance_policies(id),property_id uuid NOT NULL REFERENCES properties(id),asset_id uuid REFERENCES assets(id),opened_by_user_id uuid NOT NULL REFERENCES app_users(id),external_claim_number text,occurrence_at timestamptz NOT NULL,description text NOT NULL CHECK(length(description) BETWEEN 3 AND 5000),status text NOT NULL DEFAULT 'opened' CHECK(status IN('opened','documents_requested','under_review','approved','denied','paid','closed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX idx_insurance_claims_policy_status ON insurance_claims(policy_id,status,created_at DESC);
CREATE TABLE insurance_data_consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),property_id uuid NOT NULL REFERENCES properties(id),asset_id uuid REFERENCES assets(id),granted_by_user_id uuid NOT NULL REFERENCES app_users(id),purpose text NOT NULL CHECK(purpose IN('quote_support','risk_analysis','claim_support')),recipient_partner text,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','revoked','expired')),granted_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,revoked_at timestamptz,CONSTRAINT insurance_consent_expiry_valid CHECK(expires_at IS NULL OR expires_at>granted_at));CREATE INDEX idx_insurance_consents_scope ON insurance_data_consents(property_id,asset_id,status,expires_at);ALTER TABLE insurance_quote_requests ADD CONSTRAINT insurance_quote_security_consent_fkey FOREIGN KEY(security_consent_id) REFERENCES insurance_data_consents(id);
CREATE TABLE insurance_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),quote_request_id uuid REFERENCES insurance_quote_requests(id),policy_id uuid REFERENCES insurance_policies(id),claim_id uuid REFERENCES insurance_claims(id),document_type text NOT NULL,title text NOT NULL,storage_status text NOT NULL DEFAULT 'not_configured' CHECK(storage_status IN('not_configured','private_future')),expires_at date,created_by_user_id uuid NOT NULL REFERENCES app_users(id),created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT insurance_document_one_parent CHECK(num_nonnulls(quote_request_id,policy_id,claim_id)=1),CONSTRAINT insurance_document_title_length CHECK(length(title) BETWEEN 2 AND 160));
ALTER TABLE insurance_quote_requests ENABLE ROW LEVEL SECURITY;ALTER TABLE insurance_policies ENABLE ROW LEVEL SECURITY;ALTER TABLE insurance_claims ENABLE ROW LEVEL SECURITY;ALTER TABLE insurance_data_consents ENABLE ROW LEVEL SECURITY;ALTER TABLE insurance_documents ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION app_is_property_owner(p_property_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$SELECT EXISTS(SELECT 1 FROM memberships m JOIN app_users u ON u.id=m.user_id WHERE u.auth_user_id=NULLIF(auth.user_id(),'')::uuid AND u.status='active' AND m.status='active' AND m.property_id=p_property_id AND m.role='owner')$$;CREATE OR REPLACE FUNCTION app_can_view_insurance_scope(p_organization_id uuid,p_property_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$SELECT app_is_platform_admin() OR EXISTS(SELECT 1 FROM memberships m JOIN app_users u ON u.id=m.user_id WHERE u.auth_user_id=NULLIF(auth.user_id(),'')::uuid AND u.status='active' AND m.status='active' AND m.organization_id=p_organization_id AND(m.role='admin_organization' OR(m.property_id=p_property_id AND m.role='owner')))$$;
CREATE POLICY insurance_quotes_scope_read ON insurance_quote_requests FOR SELECT TO authenticated USING(app_can_view_insurance_scope(organization_id,property_id));CREATE POLICY insurance_policies_scope_read ON insurance_policies FOR SELECT TO authenticated USING(app_can_view_insurance_scope(organization_id,property_id));CREATE POLICY insurance_claims_scope_read ON insurance_claims FOR SELECT TO authenticated USING(app_can_view_insurance_scope(organization_id,property_id));CREATE POLICY insurance_consents_scope_read ON insurance_data_consents FOR SELECT TO authenticated USING(app_can_view_insurance_scope(organization_id,property_id));CREATE POLICY insurance_documents_scope_read ON insurance_documents FOR SELECT TO authenticated USING((quote_request_id IS NOT NULL AND EXISTS(SELECT 1 FROM insurance_quote_requests q WHERE q.id=insurance_documents.quote_request_id AND app_can_view_insurance_scope(q.organization_id,q.property_id))) OR(policy_id IS NOT NULL AND EXISTS(SELECT 1 FROM insurance_policies p WHERE p.id=insurance_documents.policy_id AND app_can_view_insurance_scope(p.organization_id,p.property_id))) OR(claim_id IS NOT NULL AND EXISTS(SELECT 1 FROM insurance_claims c WHERE c.id=insurance_documents.claim_id AND app_can_view_insurance_scope(c.organization_id,c.property_id))));REVOKE INSERT,UPDATE,DELETE ON insurance_quote_requests,insurance_policies,insurance_claims,insurance_data_consents,insurance_documents FROM authenticated,anonymous;GRANT SELECT ON insurance_quote_requests,insurance_policies,insurance_claims,insurance_data_consents,insurance_documents TO authenticated;
CREATE OR REPLACE FUNCTION create_insurance_quote_request(p_property_id uuid,p_asset_id uuid,p_product_type text,p_notes text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_asset_prop uuid;v_id uuid:=gen_random_uuid();v_user uuid:=app_current_user_id();BEGIN SELECT organization_id INTO v_org FROM properties WHERE id=p_property_id;IF NOT FOUND THEN RAISE EXCEPTION 'property_not_found';END IF;IF NOT app_can_view_insurance_scope(v_org,p_property_id) THEN RAISE EXCEPTION 'insurance_access_required';END IF;IF p_asset_id IS NOT NULL THEN SELECT property_id INTO v_asset_prop FROM assets WHERE id=p_asset_id;IF NOT FOUND OR v_asset_prop IS DISTINCT FROM p_property_id THEN RAISE EXCEPTION 'asset_scope_mismatch';END IF;END IF;INSERT INTO insurance_quote_requests(id,organization_id,property_id,asset_id,requested_by_user_id,product_type,status,security_data_use,notes) VALUES(v_id,v_org,p_property_id,p_asset_id,v_user,p_product_type,'requested',false,NULLIF(btrim(p_notes),''));RETURN v_id;END$$;GRANT EXECUTE ON FUNCTION create_insurance_quote_request(uuid,uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION grant_insurance_security_consent(p_property_id uuid,p_asset_id uuid,p_purpose text,p_recipient_partner text DEFAULT NULL,p_expires_at timestamptz DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_asset_prop uuid;v_id uuid:=gen_random_uuid();v_user uuid:=app_current_user_id();BEGIN SELECT organization_id INTO v_org FROM properties WHERE id=p_property_id;IF NOT FOUND THEN RAISE EXCEPTION 'property_not_found';END IF;IF NOT app_is_property_owner(p_property_id) THEN RAISE EXCEPTION 'property_owner_consent_required';END IF;IF p_purpose NOT IN('quote_support','risk_analysis','claim_support') THEN RAISE EXCEPTION 'invalid_consent_purpose';END IF;IF p_expires_at IS NOT NULL AND p_expires_at<=now() THEN RAISE EXCEPTION 'invalid_consent_expiry';END IF;IF p_asset_id IS NOT NULL THEN SELECT property_id INTO v_asset_prop FROM assets WHERE id=p_asset_id;IF NOT FOUND OR v_asset_prop IS DISTINCT FROM p_property_id THEN RAISE EXCEPTION 'asset_scope_mismatch';END IF;END IF;INSERT INTO insurance_data_consents(id,organization_id,property_id,asset_id,granted_by_user_id,purpose,recipient_partner,status,expires_at) VALUES(v_id,v_org,p_property_id,p_asset_id,v_user,p_purpose,NULLIF(btrim(p_recipient_partner),''),'active',p_expires_at);RETURN v_id;END$$;GRANT EXECUTE ON FUNCTION grant_insurance_security_consent(uuid,uuid,text,text,timestamptz) TO authenticated;
CREATE OR REPLACE FUNCTION revoke_insurance_security_consent(p_consent_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_prop uuid;BEGIN SELECT property_id INTO v_prop FROM insurance_data_consents WHERE id=p_consent_id;IF NOT FOUND THEN RAISE EXCEPTION 'consent_not_found';END IF;IF NOT app_is_property_owner(v_prop) THEN RAISE EXCEPTION 'property_owner_consent_required';END IF;UPDATE insurance_data_consents SET status='revoked',revoked_at=now() WHERE id=p_consent_id AND status='active';UPDATE insurance_quote_requests SET security_data_use=false,security_consent_id=NULL,updated_at=now() WHERE security_consent_id=p_consent_id AND status NOT IN('accepted','cancelled');RETURN true;END$$;GRANT EXECUTE ON FUNCTION revoke_insurance_security_consent(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION enable_quote_security_data(p_quote_id uuid,p_consent_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE q insurance_quote_requests%ROWTYPE;c insurance_data_consents%ROWTYPE;BEGIN SELECT * INTO q FROM insurance_quote_requests WHERE id=p_quote_id;IF NOT FOUND THEN RAISE EXCEPTION 'quote_not_found';END IF;IF NOT app_can_view_insurance_scope(q.organization_id,q.property_id) THEN RAISE EXCEPTION 'insurance_access_required';END IF;SELECT * INTO c FROM insurance_data_consents WHERE id=p_consent_id;IF NOT FOUND THEN RAISE EXCEPTION 'consent_not_found';END IF;IF c.status<>'active' OR(c.expires_at IS NOT NULL AND c.expires_at<=now()) OR c.purpose<>'quote_support' OR c.organization_id<>q.organization_id OR c.property_id<>q.property_id OR(c.asset_id IS NOT NULL AND c.asset_id IS DISTINCT FROM q.asset_id) THEN RAISE EXCEPTION 'active_quote_consent_required';END IF;UPDATE insurance_quote_requests SET security_data_use=true,security_consent_id=p_consent_id,updated_at=now() WHERE id=p_quote_id;RETURN true;END$$;GRANT EXECUTE ON FUNCTION enable_quote_security_data(uuid,uuid) TO authenticated;
-- Registro de apólice/sinistro representa acompanhamento de parceiros externos.
CREATE OR REPLACE FUNCTION record_insurance_policy(p_property_id uuid,p_asset_id uuid,p_product_type text,p_insurer_name text,p_policy_number text,p_coverage_summary text,p_valid_from date,p_valid_until date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_asset_prop uuid;v_id uuid:=gen_random_uuid();v_status text;BEGIN SELECT organization_id INTO v_org FROM properties WHERE id=p_property_id;IF NOT FOUND THEN RAISE EXCEPTION 'property_not_found';END IF;IF NOT app_can_view_insurance_scope(v_org,p_property_id) THEN RAISE EXCEPTION 'insurance_access_required';END IF;IF COALESCE(btrim(p_insurer_name),'')='' OR p_valid_until<p_valid_from THEN RAISE EXCEPTION 'invalid_policy';END IF;IF p_asset_id IS NOT NULL THEN SELECT property_id INTO v_asset_prop FROM assets WHERE id=p_asset_id;IF NOT FOUND OR v_asset_prop IS DISTINCT FROM p_property_id THEN RAISE EXCEPTION 'asset_scope_mismatch';END IF;END IF;v_status:=CASE WHEN p_valid_until<current_date THEN 'expired' WHEN p_valid_until<=current_date+30 THEN 'pending_renewal' ELSE 'active' END;INSERT INTO insurance_policies(id,organization_id,property_id,asset_id,product_type,insurer_name,policy_number,coverage_summary,valid_from,valid_until,status,created_by_user_id) VALUES(v_id,v_org,p_property_id,p_asset_id,p_product_type,btrim(p_insurer_name),NULLIF(btrim(p_policy_number),''),NULLIF(btrim(p_coverage_summary),''),p_valid_from,p_valid_until,v_status,app_current_user_id());RETURN v_id;END$$;GRANT EXECUTE ON FUNCTION record_insurance_policy(uuid,uuid,text,text,text,text,date,date) TO authenticated;
CREATE OR REPLACE FUNCTION update_insurance_renewal(p_policy_id uuid,p_renewal_status text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_prop uuid;BEGIN SELECT organization_id,property_id INTO v_org,v_prop FROM insurance_policies WHERE id=p_policy_id;IF NOT FOUND THEN RAISE EXCEPTION 'policy_not_found';END IF;IF NOT app_can_view_insurance_scope(v_org,v_prop) THEN RAISE EXCEPTION 'insurance_access_required';END IF;UPDATE insurance_policies SET renewal_status=p_renewal_status,status=CASE WHEN p_renewal_status='renewed' THEN 'active' WHEN valid_until<=current_date+30 AND status='active' THEN 'pending_renewal' ELSE status END,updated_at=now() WHERE id=p_policy_id;RETURN true;END$$;GRANT EXECUTE ON FUNCTION update_insurance_renewal(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION open_insurance_claim(p_policy_id uuid,p_occurrence_at timestamptz,p_description text,p_external_claim_number text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE pol insurance_policies%ROWTYPE;v_id uuid:=gen_random_uuid();BEGIN SELECT * INTO pol FROM insurance_policies WHERE id=p_policy_id;IF NOT FOUND THEN RAISE EXCEPTION 'policy_not_found';END IF;IF NOT app_can_view_insurance_scope(pol.organization_id,pol.property_id) THEN RAISE EXCEPTION 'insurance_access_required';END IF;IF p_occurrence_at IS NULL OR p_occurrence_at>now()+interval '5 minutes' OR COALESCE(btrim(p_description),'')='' THEN RAISE EXCEPTION 'invalid_claim';END IF;INSERT INTO insurance_claims(id,organization_id,policy_id,property_id,asset_id,opened_by_user_id,external_claim_number,occurrence_at,description,status) VALUES(v_id,pol.organization_id,p_policy_id,pol.property_id,pol.asset_id,app_current_user_id(),NULLIF(btrim(p_external_claim_number),''),p_occurrence_at,btrim(p_description),'opened');RETURN v_id;END$$;GRANT EXECUTE ON FUNCTION open_insurance_claim(uuid,timestamptz,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION update_insurance_claim_status(p_claim_id uuid,p_status text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_prop uuid;BEGIN SELECT organization_id,property_id INTO v_org,v_prop FROM insurance_claims WHERE id=p_claim_id;IF NOT FOUND THEN RAISE EXCEPTION 'claim_not_found';END IF;IF NOT app_can_view_insurance_scope(v_org,v_prop) THEN RAISE EXCEPTION 'insurance_access_required';END IF;UPDATE insurance_claims SET status=p_status,updated_at=now() WHERE id=p_claim_id;RETURN true;END$$;GRANT EXECUTE ON FUNCTION update_insurance_claim_status(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION add_insurance_document(p_quote_request_id uuid,p_policy_id uuid,p_claim_id uuid,p_document_type text,p_title text,p_expires_at date DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_prop uuid;v_id uuid:=gen_random_uuid();BEGIN IF num_nonnulls(p_quote_request_id,p_policy_id,p_claim_id)<>1 THEN RAISE EXCEPTION 'one_parent_required';END IF;IF p_quote_request_id IS NOT NULL THEN SELECT organization_id,property_id INTO v_org,v_prop FROM insurance_quote_requests WHERE id=p_quote_request_id;ELSIF p_policy_id IS NOT NULL THEN SELECT organization_id,property_id INTO v_org,v_prop FROM insurance_policies WHERE id=p_policy_id;ELSE SELECT organization_id,property_id INTO v_org,v_prop FROM insurance_claims WHERE id=p_claim_id;END IF;IF v_org IS NULL OR NOT app_can_view_insurance_scope(v_org,v_prop) THEN RAISE EXCEPTION 'insurance_access_required';END IF;INSERT INTO insurance_documents(id,organization_id,quote_request_id,policy_id,claim_id,document_type,title,storage_status,expires_at,created_by_user_id) VALUES(v_id,v_org,p_quote_request_id,p_policy_id,p_claim_id,btrim(p_document_type),btrim(p_title),'not_configured',p_expires_at,app_current_user_id());RETURN v_id;END$$;GRANT EXECUTE ON FUNCTION add_insurance_document(uuid,uuid,uuid,text,text,date) TO authenticated;
CREATE OR REPLACE FUNCTION get_insurance_quotes() RETURNS TABLE(id uuid,property_id uuid,property_name text,asset_id uuid,asset_name text,product_type text,status text,security_data_use boolean,security_consent_id uuid,created_at timestamptz,updated_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$SELECT q.id,q.property_id,p.name,q.asset_id,a.name,q.product_type,q.status,q.security_data_use,q.security_consent_id,q.created_at,q.updated_at FROM insurance_quote_requests q JOIN properties p ON p.id=q.property_id LEFT JOIN assets a ON a.id=q.asset_id WHERE app_can_view_insurance_scope(q.organization_id,q.property_id) ORDER BY q.created_at DESC$$;GRANT EXECUTE ON FUNCTION get_insurance_quotes() TO authenticated;
CREATE OR REPLACE FUNCTION get_insurance_policies() RETURNS TABLE(id uuid,property_id uuid,property_name text,asset_id uuid,asset_name text,product_type text,insurer_name text,policy_number text,coverage_summary text,valid_from date,valid_until date,status text,renewal_status text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$SELECT pol.id,pol.property_id,p.name,pol.asset_id,a.name,pol.product_type,pol.insurer_name,pol.policy_number,pol.coverage_summary,pol.valid_from,pol.valid_until,pol.status,pol.renewal_status,pol.created_at FROM insurance_policies pol JOIN properties p ON p.id=pol.property_id LEFT JOIN assets a ON a.id=pol.asset_id WHERE app_can_view_insurance_scope(pol.organization_id,pol.property_id) ORDER BY pol.valid_until,pol.created_at DESC$$;GRANT EXECUTE ON FUNCTION get_insurance_policies() TO authenticated;
CREATE OR REPLACE FUNCTION get_insurance_claims() RETURNS TABLE(id uuid,policy_id uuid,property_id uuid,property_name text,asset_id uuid,asset_name text,insurer_name text,external_claim_number text,occurrence_at timestamptz,description text,status text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$SELECT c.id,c.policy_id,c.property_id,p.name,c.asset_id,a.name,pol.insurer_name,c.external_claim_number,c.occurrence_at,c.description,c.status,c.created_at FROM insurance_claims c JOIN insurance_policies pol ON pol.id=c.policy_id JOIN properties p ON p.id=c.property_id LEFT JOIN assets a ON a.id=c.asset_id WHERE app_can_view_insurance_scope(c.organization_id,c.property_id) ORDER BY c.created_at DESC$$;GRANT EXECUTE ON FUNCTION get_insurance_claims() TO authenticated;
CREATE OR REPLACE FUNCTION get_insurance_consents() RETURNS TABLE(id uuid,property_id uuid,property_name text,asset_id uuid,asset_name text,purpose text,recipient_partner text,status text,granted_at timestamptz,expires_at timestamptz,revoked_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$SELECT c.id,c.property_id,p.name,c.asset_id,a.name,c.purpose,c.recipient_partner,CASE WHEN c.status='active' AND c.expires_at IS NOT NULL AND c.expires_at<=now() THEN 'expired' ELSE c.status END,c.granted_at,c.expires_at,c.revoked_at FROM insurance_data_consents c JOIN properties p ON p.id=c.property_id LEFT JOIN assets a ON a.id=c.asset_id WHERE app_can_view_insurance_scope(c.organization_id,c.property_id) ORDER BY c.granted_at DESC$$;GRANT EXECUTE ON FUNCTION get_insurance_consents() TO authenticated;
